import { Auth } from './auth.js';

function esc(value) { return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) { return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]; }); }
function n(value) { return Math.max(0, Number(value) || 0); }
function pct(value) { return Math.max(0, Math.min(100, Math.round(n(value)))); }
function time(value) { value = Math.round(n(value)); if (value < 60) return value ? '<1m' : '0m'; var h = Math.floor(value / 3600), m = Math.round(value % 3600 / 60); return h ? h + 'h ' + m + 'm' : m + 'm'; }
function initials(value) { return String(value || '?').trim().split(/\s+|@/).map(function (part) { return part.charAt(0); }).join('').slice(0, 2).toUpperCase(); }
function rootUrl(path) { return new URL(path, new URL('../', import.meta.url)).href; }
function profileName(person) { return (person && (person.display_name || person.name || person.email)) || 'Student'; }
function roleName(role) { return role === 'admin' ? 'Administrator' : role === 'professor' ? 'Professor' : 'Student'; }
function courseLabel(course) { var code = String(course && course.code || '').trim(), title = String(course && course.title || '').trim(); return code && title && title.toUpperCase().indexOf(code.toUpperCase()) === 0 ? title : [code, title].filter(Boolean).join(' — '); }
function renderMath(node) { if (!node) return; if (window.StudyMath && window.StudyMath.render) return window.StudyMath.render(node); if (window.renderMathInElement) window.renderMathInElement(node, { delimiters: [{ left: '$$', right: '$$', display: true }, { left: '$', right: '$', display: false }], throwOnError: false }); }

