      m.innerHTML = '<button class="modal-x" type="button" aria-label="Close" data-close>×</button><div class="class-review"><div class="control-eyebrow">' + esc(course.subject || 'Course') + ' · protected class view</div><div class="class-review-title"><div><h2>' + esc(courseLabel(course) || section.section_label) + '</h2><p class="modal-sub">' + esc(section.section_label) + (section.term ? ' · ' + esc(section.term) : '') + '</p></div><span class="panel-chip">' + students.length + ' enrolled</span></div><p class="review-description">' + esc(course.description || 'Review the lessons, class roster, and learning progress for this section.') + '</p><div class="account-grid review-metrics">' + metricCard(active.length, 'Active student accounts', 'green') + metricCard(active.length ? Math.round(totals.completion / active.length) + '%' : '—', 'Average completion', 'orange') + metricCard(totals.xp, 'Class XP', 'violet') + metricCard(time(totals.time), 'Recorded study time', 'blue') + '</div><div class="review-tabs"><button class="active" data-review-tab="content">Class content</button><button data-review-tab="learn">Learn checks</button><button data-review-tab="practice">Practice problems</button><button data-review-tab="students">Students (' + students.length + ')</button><button data-review-tab="activity">Activity</button></div><div id="review-body"></div><div class="modal-actions"><button class="btn subtle" data-close>Close</button></div></div>';
